/**
 * Reject a pickup request before payment
 *
 * Only a PENDING_ACCEPTANCE order can be rejected. No provider payment session is created, and reserved points are released.
 */
export const reject = <ThrowOnError extends boolean = true>(options: Options<RejectData, ThrowOnError>): RequestResult<RejectResponses, unknown, ThrowOnError> => (options.client ?? client).post<RejectResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/staff/orders/{orderId}/reject',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Mark a preparing pickup ready
 *
 * The order must be PREPARING. This transition changes it to READY. Reuse clientRequestId when retrying the same command.
 */
export const ready = <ThrowOnError extends boolean = true>(options: Options<ReadyData, ThrowOnError>): RequestResult<ReadyResponses, unknown, ThrowOnError> => (options.client ?? client).post<ReadyResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/staff/orders/{orderId}/ready',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Atomically settle and complete a ready pickup
 *
 * The order must be READY. This transition changes it to COMPLETED. Reuse clientRequestId when retrying the same command.
 */
export const complete = <ThrowOnError extends boolean = true>(options: Options<CompleteData, ThrowOnError>): RequestResult<CompleteResponses, unknown, ThrowOnError> => (options.client ?? client).post<CompleteResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/staff/orders/{orderId}/complete',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Cancel an eligible pickup order
 *
 * Cancellation requires a reason and clientRequestId, and is rejected for terminal orders. Reuse clientRequestId when retrying the same command.
 */
