/**
 * List food pickup orders
 *
 * Optionally filter by ALL, an active queue, or terminal-history status and search by order, invoice, customer, member, or item before pagination. ALL covers CONFIRMED, PREPARING, READY, COMPLETED, NOT_COLLECTED, and CANCELLED. Omit status to return the combined CONFIRMED, PREPARING, and READY operational queue.
 */
export const pickupQueue = <ThrowOnError extends boolean = true>(options?: Options<PickupQueueData, ThrowOnError>): RequestResult<PickupQueueResponses, unknown, ThrowOnError> => (options?.client ?? client).get<PickupQueueResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/staff/orders/pickup-queue',
    ...options
});

/**
 * Summarize the food pickup queue
 *
 * Returns authoritative counts for CONFIRMED, PREPARING, READY, COMPLETED, NOT_COLLECTED, and CANCELLED using the same eligibility rules as the queue. Legacy acceptance and hidden payment states are excluded from normal queue counters.
 */
